async function clearCheck(id){if(ledgerSaving)return;const c=fin.checks.find(x=>x.id===id),o=fin.obligations.find(x=>x.id===c?.obligationId),date=S(document.getElementById('finCClearDate')?.value),accountKey=S(document.getElementById('finCClearAccount')?.value);if(!c||!o||!date||!accountRows().some(x=>x.key===accountKey))return toast('تاریخ و حساب / محل وجه معتبر الزامی است',true);const existing=fin.settlements.find(x=>x.sourceCheckId===id&&active(x));if(existing){c.status='cleared';c.clearedDate=existing.date;return toast('تسویه این چک قبلاً ثبت شده است')}if(c.status!=='pending'||N(c.amountToman)>calcObligation(o).balance)return toast('وضعیت یا مانده سند اجازه تأیید این چک را نمی‌دهد',true);const snap=snapshot(),sid=uid('SET',fin.settlements);fin.settlements.push({id:sid,requestId:`CHECK-${id}`,sourceCheckId:id,obligationId:o.id,direction:o.direction==='payable'?'payment':'receipt',accountKey,reference:`CHECK:${id}:${c.number}`,date,amountToman:N(c.amountToman),method:'چک',notes:`${c.type==='issued'?'پاس':'وصول'} چک ${c.number}`,status:'active',createdAt:now()});Object.assign(c,{status:'cleared',clearedDate:date,settlementId:sid,updatedAt:now()});ledgerSaving=true;document.getElementById('finModalSave').disabled=true;try{await save('تأیید پاس یا وصول چک');closeModal();renderView()}catch(e){restore(snap);toast('ثبت تأیید چک ناموفق بود؛ دوباره‌کاری ایجاد نشد',true);document.getElementById('finModalSave').disabled=false}finally{ledgerSaving=false}}
async function reverseCheck(id,next='returned'){const c=fin.checks.find(x=>x.id===id);if(!c)return;const reason=S(prompt('علت برگشت/ابطال را وارد کنید:')||'');if(!reason)return;const snap=snapshot(),linked=fin.settlements.find(x=>x.sourceCheckId===id&&active(x));if(linked)Object.assign(linked,{status:'void',voidReason:reason,voidedAt:now()});Object.assign(c,{status:next,voidReason:reason,updatedAt:now()});try{await save('اصلاح وضعیت چک و برگشت اثر تسویه');closeModal();renderView()}catch(e){restore(snap);toast('اصلاح وضعیت چک ذخیره نشد',true)}}
async function voidObligation(id){const o=fin.obligations.find(x=>x.id===id);if(!o)return;const links=validSettlements(id).length+fin.checks.filter(x=>x.obligationId===id&&active(x)).length,reason=S(prompt(`${links?'این سند وابستگی مالی دارد. ':''}علت ابطال را وارد کنید:`)||'');if(!reason)return;if(links)return toast('ابتدا تسویه و چک‌های مرتبط را ابطال کنید؛ اثر وجه نباید از سند جدا شود',true);const snap=snapshot();Object.assign(o,{status:'void',voidReason:reason,voidedAt:now()});try{await save('ابطال تعهد مالی');closeModal();renderView()}catch(e){restore(snap);toast('ابطال ذخیره نشد',true)}}
