function accountRows(){return [...A(support.cash?.transferAccounts).map(x=>({key:`account:${x.id}`,name:`کارت / حساب: ${x.name}`})),...A(support.cash?.cashRecipients).map(x=>({key:`cash:${x.id}`,name:`نقد نزد: ${x.name}`})),...A(support.inventory?.settings?.paymentLocations).map(x=>({key:`payment:${x.id}`,name:`محل پرداخت: ${x.name}`}))]}
function accountOptions(){return '<option value="">انتخاب کنید</option>'+accountRows().map(x=>`<option value="${E(x.key)}">${E(x.name)}</option>`).join('')}
function cashEvents(){
 const rows=[],push=(source,row,date,amount,key,description)=>{if(active(row)&&Number.isFinite(amount)&&amount!==0)rows.push({id:`${source}:${row.id}`,date:S(date),amount,key:key||'',description,reference:S(row.reference||row.tracking||row.id)})};
 for(const e of A(fin.entries))if(e.type!=='openingBalance'&&!e.obligationId&&!e.sourcePaymentId)push('finance',e,e.date,(e.type==='income'?1:-1)*N(e.amountToman),e.accountKey||(e.accountId?`account:${e.accountId}`:e.cashRecipientId?`cash:${e.cashRecipientId}`:''),e.title||'گردش مالی');
 for(const e of A(fin.settlements))push('settlement',e,e.date,(e.direction==='receipt'?1:-1)*N(e.amountToman),e.accountKey,'تسویه '+e.obligationId);
 for(const e of A(support.inventory?.supplierPayments)){const sign=window.RayoPaymentOptions?.directionSign?.(e,support.inventory)??(e.direction==='receipt'?-1:1);push('supplierPayment',e,e.date,-sign*N(e.amount),e.paymentLocationId?`payment:${e.paymentLocationId}`:'','تسویه طرف تجاری')}
 for(const e of A(support.inventory?.purchaseInvoices))if(!['draft','pending','rejected'].includes(e.status))push('invoicePayment',e,e.date,-N(e.paidAmount),e.paymentLocationId?`payment:${e.paymentLocationId}`:'','پرداخت هم‌زمان فاکتور');
 for(const e of A(support.hr?.payments))push('payrollPayment',e,e.date,-N(e.amount),e.accountKey||'','پرداخت حقوق / انعام');
 for(const e of A(support.cash?.reports)){
  push('cardToCard',e,e.date,N(e.cardToCard)/10,e.cardToCardAccountId?`account:${e.cardToCardAccountId}`:'','کارت‌به‌کارت صندوق');
  push('cash',e,e.date,N(e.cash)/10,e.cashRecipientId?`cash:${e.cashRecipientId}`:'','نقد تحویل‌شده صندوق');
  for(let i=1;i<=6;i++)push(`pos${i}`,e,e.date,N(e[`pos${i}`])/10,'',`کارتخوان ${i}؛ حساب مقصد مشخص نیست`);
 }
 return rows;
}
function accountPosition(key,date=day()){
 const opening=A(fin.entries).filter(x=>active(x)&&x.type==='openingBalance'&&x.accountKey===key&&x.date<=date).sort((a,b)=>S(b.date).localeCompare(S(a.date)))[0];
 const events=cashEvents().filter(x=>x.key===key&&x.date<=date&&(!opening||x.date>opening.date));
 return {opening,events,balance:opening?N(opening.amountToman)+events.reduce((n,x)=>n+x.amount,0):null};
}
function auditOpening(){
 const warnings=[],groups=new Map(),check=(kind,rows,key)=>{for(const x of rows.filter(active)){const k=key(x);if(!k)continue;const id=kind+':'+k,prev=groups.get(id);if(prev)warnings.push(`${kind}: ${prev.id} / ${x.id}`);else groups.set(id,x)}};
 check('فاکتور تکراری',A(support.inventory?.purchaseInvoices),x=>(x.number||x.invoiceNumber)?`${x.supplierId}:${norm(x.number||x.invoiceNumber)}`:'');
 check('پرداخت تکراری',A(support.inventory?.supplierPayments),x=>x.reference?`${x.paymentLocationId}:${norm(x.reference)}`:'');
 check('تسویه تکراری',A(fin.settlements),x=>x.reference?`${x.accountKey}:${norm(x.reference)}`:x.requestId||'');
 check('مرجع وجه مشترک بین ماژول‌ها',[...A(support.inventory?.supplierPayments).map(x=>({...x,id:`تأمین:${x.id}`,auditAccount:x.paymentLocationId?`payment:${x.paymentLocationId}`:'',auditReference:x.reference})),...A(fin.settlements).map(x=>({...x,id:`مالی:${x.id}`,auditAccount:x.accountKey,auditReference:x.reference})),...A(support.hr?.payments).map(x=>({...x,id:`حقوق:${x.id}`,auditAccount:x.accountKey,auditReference:x.tracking}))],x=>x.auditAccount&&x.auditReference?`${x.auditAccount}:${norm(x.auditReference)}`:'');
 check('اثر انبار تکراری',A(support.inventory?.inventoryMovements),x=>x.sourceKey);
 check('افتتاحیه طرف تکراری',A(support.inventory?.supplierDirectDebts).filter(x=>x.debtType==='opening'),x=>x.supplierId+':'+x.baselineDate);
 for(const o of fin.obligations.filter(active))if(o.partySource==='suppliers')warnings.push(`احتمال هم‌پوشانی مالی و تأمین: ${o.id}؛ با حساب طرف تطبیق دهید`);
 for(const o of fin.obligations.filter(x=>active(x)&&x.entryType==='opening'))if(fin.obligations.some(x=>active(x)&&x.id!==o.id&&x.partySource===o.partySource&&x.partyId===o.partyId&&x.date<=o.date))warnings.push(`افتتاحیه با سابقه قبلی هم‌پوشان است: ${o.id}`);
 return warnings;
}
let openingPreview=null;
function openingView(){const events=cashEvents().filter(x=>inMonth(x.date,ui.year,ui.month)),warnings=auditOpening(),missing=Object.keys(support).filter(k=>!support[k]);return `<div class="card"><h2>شروع عملیات ۱ مهر ۱۴۰۵</h2><p>افتتاحیه یعنی مانده پایان شهریور؛ خرید، درآمد یا هزینه مهر نیست. عملیات جدید فقط در ماژول اصلی ثبت می‌شود. تسویه فقط بدهی/طلب و وجه را تغییر می‌دهد؛ آن را دوباره در «سایر هزینه / درآمد» وارد نکنید.</p><p>ابتدا از <a href="settings.html?view=dataManagement">مدیریت اطلاعات و بکاپ</a> پشتیبان بگیرید. مبنای پایان روز: <b>۱۴۰۵/۰۶/۳۱</b>؛ عملیات جدید: از <b>۱۴۰۵/۰۷/۰۱</b>.</p><p><a class="btn" href="suppliers.html?tab=accounts">افتتاحیه طرف‌های تجاری</a> <a class="btn" href="personnel.html?view=payroll">افتتاحیه پرسنل: کارکرد ماه ← ورودی دستی</a> <a class="btn" href="inventory.html?tab=count">مقدار و ارزش اولیه انبار</a> <button class="btn" onclick="finTab('payables')">بدهی عمومی</button> <button class="btn" onclick="finTab('receivables')">طلب عمومی</button></p><p class="muted">برای پرسنل، سال ۱۴۰۵ و ماه مهر را انتخاب کنید؛ مانده اعلامی جای مانده قبل می‌نشیند. در انبار، شمارش اولیه پایان شهریور پس از تأیید جای سابقه مقداری همان محل را می‌گیرد. خانه خالی یعنی نامعلوم، نه صفر.</p></div><div class="card"><h2>افتتاحیه صندوق / بانک</h2><p>مانده پایان تاریخ مبنا جای گردش قبل از آن می‌نشیند؛ دوباره با آن جمع نمی‌شود. حساب‌های هم‌نام از دو فهرست خودکار یکی نمی‌شوند.</p><div class="form-grid"><div class="field"><label>حساب / محل *</label><select id="finOpeningAccount">${accountOptions()}</select></div><div class="field"><label>پایان روز مبنا *</label><input id="finOpeningDate" data-jalali="1" value="1405/06/31"></div><div class="field"><label>مانده اعلامی (تومان؛ منفی مجاز) *</label><input id="finOpeningAmount" inputmode="decimal" placeholder="نامعلوم؛ وارد نشده"></div><div class="field"><label>شرح *</label><input id="finOpeningNote"></div></div><button class="btn" onclick="finPreviewOpening()">پیش‌نمایش و دانلود پشتیبان مالی</button><div id="finOpeningPreview" role="status"></div><button class="btn btn-primary" onclick="finSaveOpening()">تأیید و ثبت افتتاحیه</button></div>${filter()}<div class="card"><h2>مانده حساب‌ها تا پایان ماه انتخابی</h2><p>مانده‌ها بر اساس گردش‌های دارای حساب مشخص‌اند. پرداخت‌های قدیمی با مبدأ متنی و کارتخوان بدون نگاشت، تخصیص داده نمی‌شوند.</p><table class="data-table"><thead><tr><th>حساب</th><th>مبنا</th><th>مانده ثبت‌شده</th><th></th></tr></thead><tbody>${accountRows().map(a=>{const p=accountPosition(a.key,`${ui.year}/${String(ui.month).padStart(2,'0')}/${ui.month<=6?'31':'30'}`);return `<tr><td>${E(a.name)}</td><td>${E(p.opening?.date||'نامعلوم')}</td><td>${p.balance===null?'نامعلوم؛ افتتاحیه ثبت نشده':M(p.balance)}</td><td>${p.opening?`<button class="btn btn-sm" onclick="finVoidOpening('${E(p.opening.id)}')">ابطال / اصلاح مبنا</button>`:''}</td></tr>`}).join('')}</tbody></table></div><div class="card"><h2>گردش نقدی ماه (مستقل از هزینه و درآمد)</h2><p>ورود: ${M(events.reduce((a,x)=>a+Math.max(0,x.amount),0))} — خروج: ${M(events.reduce((a,x)=>a+Math.max(0,-x.amount),0))}</p>${missing.length?`<p class="danger-text">جمع ناقص؛ منابع دریافت‌نشده: ${E(missing.join('، '))}</p>`:''}<p>گردش بدون حساب مشخص: ${F(events.filter(x=>!x.key).length)} مورد؛ مانده حساب‌ها تا رفع این موارد قطعی نیست.</p><table class="data-table"><thead><tr><th>تاریخ</th><th>مرجع اصلی</th><th>شرح</th><th>حساب</th><th>ورود / خروج</th></tr></thead><tbody>${events.map(x=>`<tr><td>${E(x.date)}</td><td>${E(x.id)}</td><td>${E(x.description)}</td><td>${E(accountRows().find(a=>a.key===x.key)?.name||'نامعلوم')}</td><td>${M(x.amount)}</td></tr>`).join('')}</tbody></table></div><div class="card"><h2>موارد مشکوک؛ بدون حذف یا ادغام خودکار</h2>${warnings.length?warnings.map(x=>`<p>${E(x)}</p>`).join(''):'در منابع بارگذاری‌شده، تکرار دارای مرجع مشترک یافت نشد؛ این بررسی جای تطبیق اسناد بدون مرجع را نمی‌گیرد.'}</div>`}
function strictNumber(value){const raw=S(value),normalized=raw.replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).replace(/٫/g,'.').replace(/[٬,،\s]/g,'');if(!/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)$/.test(normalized))return null;const number=Number(normalized);return Number.isFinite(number)?number:null}
function openingInput(){const raw=S(document.getElementById('finOpeningAmount')?.value),number=strictNumber(raw),accountKey=S(document.getElementById('finOpeningAccount')?.value),date=S(document.getElementById('finOpeningDate')?.value),notes=S(document.getElementById('finOpeningNote')?.value);if(!raw||number===null||!accountRows().some(a=>a.key===accountKey)||!/^14\d{2}\/(0[1-9]|1[0-2])\/(0[1-9]|[12]\d|3[01])$/.test(date)||!notes)throw Error('حساب، تاریخ صفرپر، مبلغ معتبر و شرح الزامی است');if(A(fin.entries).some(x=>active(x)&&x.type==='openingBalance'&&x.accountKey===accountKey))throw Error('برای این حساب افتتاحیه موجود است؛ ابتدا آن را بررسی و در صورت نیاز ابطال کنید');return {accountKey,date,amountToman:number,notes}}
function backupFinance(){const blob=new Blob([JSON.stringify(fin,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='rayo-finance-before-opening.json';a.click();URL.revokeObjectURL(a.href)}
function previewOpening(){try{const row=openingInput(),old=cashEvents().filter(x=>x.key===row.accountKey&&x.date<=row.date).reduce((a,x)=>a+x.amount,0);backupFinance();openingPreview={row,signature:JSON.stringify(row),snapshot:snapshot(),id:`OPEN-${RAYO_API_GATEWAY.createRequestId()}`};document.getElementById('finOpeningPreview').textContent=`مانده اعلامی ${M(row.amountToman)}؛ خالص گردش قبلی ${M(old)} (جداگانه اضافه نمی‌شود). بازگشت: ابطال همین افتتاحیه. پشتیبان مالی دانلود شد.`}catch(e){toast(e.message,true)}}
