async function voidSettlement(id){const r=fin.settlements.find(x=>x.id===id&&active(x));if(!r||r.sourceCheckId||ledgerSaving)return;const reason=S(prompt('تسویه و اثر وجه با هم برمی‌گردند. برای اصلاح، پس از ابطال تسویه صحیح را ثبت کنید. علت:')||'');if(!reason)return;backupFinance();const before=snapshot();ledgerSaving=true;Object.assign(r,{status:'void',voidReason:reason,voidedAt:now()});try{await save('ابطال تسویه');viewObligation(r.obligationId);renderView()}catch(e){restore(before);toast(e.message,true)}finally{ledgerSaving=false}}
function financeAccountOptions(selected){const rows=A(support.cash?.transferAccounts);return `<option value="">انتخاب کنید</option>${rows.filter(x=>x.status!=='غیرفعال'||x.id===selected).map(x=>`<option value="${E(x.id)}" ${x.id===selected?'selected':''}>${E(x.name)}</option>`).join('')}`}
function entryModal(type='expense',row=null){const cats=type==='income'?fin.settings.incomeCategories:fin.settings.expenseCategories;document.getElementById('modalTitle').textContent=row?'ویرایش رکورد مالی':type==='income'?'ثبت دریافت':'ثبت پرداخت';document.getElementById('modalBody').innerHTML=`<div class="form-grid"><div class="field"><label>تاریخ</label><input id="finEDate" data-jalali="1" value="${E(row?.date||window.RayoJalali?.today?.()||'')}"></div><div class="field"><label>${type==='income'?'واریز به کارت/حساب':'پرداخت از کارت/حساب'}</label><select id="finEAccount">${financeAccountOptions(row?.accountId)}</select></div><div class="field"><label>دسته‌بندی</label><select id="finECat">${A(cats).map(x=>`<option ${x===row?.category?'selected':''}>${E(x)}</option>`).join('')}</select></div><div class="field"><label>مبلغ (تومان)</label><input id="finEAmt" type="number" value="${N(row?.amountToman)}"></div><div class="field"><label>عنوان/شرح کوتاه</label><input id="finETitle" value="${E(row?.title||'')}"></div><div class="field full"><label>توضیحات</label><textarea id="finENotes">${E(row?.notes||'')}</textarea></div></div>${A(support.cash?.transferAccounts).length?'':'<div class="hint">ابتدا کارت یا حساب را در تنظیمات گزارش صندوق تعریف کنید.</div>'}`;document.getElementById('modalFoot').innerHTML=`<button class="btn" onclick="closeModal()">انصراف</button><button class="btn btn-primary" onclick="finSaveEntry('${row?.id||''}','${type}')">ذخیره</button>`;document.getElementById('modalBackdrop').classList.add('open');setTimeout(()=>RayoJalali?.mark?.(),0)}
async function saveEntry(rowId,type){const accountId=S(document.getElementById('finEAccount')?.value),o={date:S(document.getElementById('finEDate')?.value),type,accountId,accountNameSnapshot:A(support.cash?.transferAccounts).find(x=>x.id===accountId)?.name||'',category:S(document.getElementById('finECat')?.value),amountToman:N(document.getElementById('finEAmt')?.value),title:S(document.getElementById('finETitle')?.value),notes:S(document.getElementById('finENotes')?.value)};if(!o.date||o.amountToman<=0||!o.accountId)return toast('تاریخ، کارت/حساب و مبلغ معتبر الزامی است',true);let r=rowId?fin.entries.find(x=>x.id===rowId):null;if(r)Object.assign(r,o,{updatedAt:now()});else fin.entries.push({id:uid('FIN',fin.entries),...o,createdAt:now()});closeModal();await save(rowId?'ویرایش رکورد مالی':'ثبت رکورد مالی');renderView()}
async function deleteEntry(rowId){if(fin.entries.find(x=>x.id===rowId)?.custodyKind)return window.crVoidCustodyEntry?.(rowId);const reason=S(prompt('علت ابطال رکورد مالی:')||'');if(!reason)return;const r=fin.entries.find(x=>x.id===rowId),before=snapshot();if(!r)return;Object.assign(r,{status:'void',voidReason:reason,voidedAt:now()});try{await save('ابطال رکورد مالی');renderView()}catch(e){restore(before);toast(e.message,true)}}
function calculator(){const d=fin.settings.calculatorDefaults||{};setTimeout(calcLive,0);return `<div class="card"><div class="section-head"><div><h2>محاسبه‌گر سود</h2><p class="muted">سناریوی سریع و مستقل از اطلاعات ثبت‌شده</p></div><button class="btn" onclick="finSaveCalculatorDefaults()">ذخیره به‌عنوان پیش‌فرض</button></div><div class="form-grid">${[['Sales','فروش ماهانه',d.sales],['PurchasePercent','مواد اولیه / خرید (% فروش)',d.purchasePercent],['Payroll','حقوق',d.payroll],['Rent','اجاره',d.rent],['Management','مدیریت',d.management],['Utilities','قبوض',d.utilities],['Maintenance','تعمیر و نگهداری',d.maintenance],['Other','سایر هزینه‌ها',d.other||0],['VatPercent','ارزش افزوده %',d.vatPercent??fin.settings.vatPercent],['TaxPercent','مالیات عملکرد %',d.performanceTaxPercent??fin.settings.performanceTaxPercent]].map(([k,l,v])=>`<div class="field"><label>${l}</label><input id="fcalc${k}" type="number" value="${N(v)}" oninput="finCalcLive()"></div>`).join('')}</div></div><div id="finCalcResult"></div>`}
function calcValues(){const g=k=>N(document.getElementById('fcalc'+k)?.value),sales=g('Sales'),purchase=sales*g('PurchasePercent')/100,payroll=g('Payroll'),fixed=g('Rent')+g('Management')+g('Utilities')+g('Maintenance')+g('Other'),tax=sales*(g('VatPercent')+g('TaxPercent'))/100,profit=sales-purchase-payroll-fixed-tax,variableRate=(g('PurchasePercent')+g('VatPercent')+g('TaxPercent'))/100,breakEven=(1-variableRate)>0?(payroll+fixed)/(1-variableRate):0;return{sales,purchase,payroll,fixed,tax,profit,breakEven,margin:sales?profit/sales*100:0}}
function calcLive(){const r=calcValues(),el=document.getElementById('finCalcResult');if(!el)return;el.innerHTML=`<div class="grid grid-4"><div class="card kpi"><div class="label">هزینه مواد</div><div class="value">${F(r.purchase)}</div></div><div class="card kpi"><div class="label">مالیات‌ها</div><div class="value">${F(r.tax)}</div></div><div class="card kpi"><div class="label">سود تقریبی</div><div class="value ${r.profit<0?'danger-text':'positive'}">${F(r.profit)}</div><div class="sub">${r.margin.toFixed(1)}٪ فروش</div></div><div class="card kpi"><div class="label">فروش سربه‌سر</div><div class="value">${F(r.breakEven)}</div></div></div>`}
async function saveCalcDefaults(){const d=fin.settings.calculatorDefaults=fin.settings.calculatorDefaults||{};d.sales=N(document.getElementById('fcalcSales')?.value);d.purchasePercent=N(document.getElementById('fcalcPurchasePercent')?.value);d.payroll=N(document.getElementById('fcalcPayroll')?.value);d.rent=N(document.getElementById('fcalcRent')?.value);d.management=N(document.getElementById('fcalcManagement')?.value);d.utilities=N(document.getElementById('fcalcUtilities')?.value);d.maintenance=N(document.getElementById('fcalcMaintenance')?.value);d.other=N(document.getElementById('fcalcOther')?.value);d.vatPercent=N(document.getElementById('fcalcVatPercent')?.value);d.performanceTaxPercent=N(document.getElementById('fcalcTaxPercent')?.value);await save('ذخیره پیش‌فرض محاسبه‌گر')}
function settings(){return `<div class="card"><div class="section-head"><h2>تنظیمات مالی</h2><button class="btn btn-primary" onclick="finSaveSettings()">ذخیره</button></div><div class="form-grid"><div class="field"><label>ارزش افزوده (% فروش)</label><input id="finVat" type="number" value="${fin.settings.vatPercent}"></div><div class="field"><label>مالیات عملکرد (% فروش)</label><input id="finTax" type="number" value="${fin.settings.performanceTaxPercent}"></div><div class="field full"><label>دسته‌های بدهی و طلب — هر مورد در یک خط</label><textarea id="finObCats">${E(A(fin.settings.obligationCategories).join('\n'))}</textarea></div><div class="field full"><label>دسته‌های هزینه — هر مورد در یک خط</label><textarea id="finExpCats">${E(A(fin.settings.expenseCategories).join('\n'))}</textarea></div><div class="field full"><label>دسته‌های درآمد — هر مورد در یک خط</label><textarea id="finIncCats">${E(A(fin.settings.incomeCategories).join('\n'))}</textarea></div></div></div>`}
async function saveSettings(){fin.settings.vatPercent=N(document.getElementById('finVat')?.value);fin.settings.performanceTaxPercent=N(document.getElementById('finTax')?.value);fin.settings.obligationCategories=S(document.getElementById('finObCats')?.value).split('\n').map(S).filter(Boolean);fin.settings.expenseCategories=S(document.getElementById('finExpCats')?.value).split('\n').map(S).filter(Boolean);fin.settings.incomeCategories=S(document.getElementById('finIncCats')?.value).split('\n').map(S).filter(Boolean);await save('ذخیره تنظیمات مالی');renderView()}
function settingsShortcut(){return `<div class="card"><div class="section-head"><h2>تنظیمات مالی</h2></div><p class="muted">ارزش افزوده، مالیات عملکرد، دسته‌های بدهی/طلب/هزینه/درآمد و پیش‌فرض محاسبه‌گر سود اکنون در «تنظیمات نرم‌افزار» ویرایش می‌شوند.</p><a class="btn btn-primary" href="settings.html?view=softwareSettings&section=finance">تنظیمات این بخش</a></div>`}
function view(){if(!finLoaded){load();return `<div class="card empty">در حال بارگذاری اطلاعات مالی…</div>`}if(loadError||!fin)return `<div class="card empty"><h2>اطلاعات مالی بارگذاری نشد</h2><p>${E(loadError)}</p><button class="btn btn-primary" onclick="finRefresh()">تلاش دوباره</button></div>`;const body=ui.tab==='opening'?openingView():ui.tab==='obligations'?obligationsHome():ui.tab==='payables'?obligationList('payable'):ui.tab==='receivables'?obligationList('receivable'):ui.tab==='checks'?checksView():ui.tab==='entries'?entries():ui.tab==='calculator'?settingsShortcut():ui.tab==='settings'?settingsShortcut():monthly();setTimeout(()=>RayoJalali?.mark?.(),0);return (typeof pageHead==='function'?pageHead('بدهی‌ها، مطالبات و چک‌ها','دفتر پیگیری داخلی تعهدات مالی؛ بدون اتصال بانکی و جایگزین حسابداری رسمی نیست'):'')+tabs()+body}
function install(){if(typeof views==='undefined'||typeof titles==='undefined')return setTimeout(install,100);titles.finance='بدهی‌ها، مطالبات و چک‌ها';views.finance=view;Object.assign(window,{uiFinance:ui,finTab:t=>{ui.tab=t;const u=new URL(location.href);u.searchParams.set('view',t);history.replaceState({},'',u);renderView()},finFilter:(k,v,typing)=>{ui[k]=v;if(typing){clearTimeout(window.__finFilterTimer);window.__finFilterTimer=setTimeout(renderView,180)}else renderView()},finClearFilters:()=>{Object.assign(ui,{search:'',category:'',status:'',dateFrom:'',dateTo:'',dueFrom:'',dueTo:'',sort:'due'});renderView()},finFilterParty:filterParty,finOpenObligation:openObligation,finSaveObligation:saveObligation,finViewObligation:viewObligation,finOpenSettlement:openSettlement,finSaveSettlement:saveSettlement,finOpenCheck:openCheck,finSaveCheck:saveCheck,finOpenClearCheck:openClearCheck,finClearCheck:clearCheck,finReverseCheck:reverseCheck,finVoidObligation:voidObligation,RayoFinanceLedger:{calcObligation,checkStatus,monthAuto,monthCalc,cashEvents,accountPosition,auditOpening},finPreviewOpening:previewOpening,finSaveOpening:saveOpening,finVoidOpening:voidOpening,finVoidSettlement:voidSettlement,finSaveOverrides:saveOverrides,finNewEntry:type=>entryModal(type),finEditEntry:id=>{const r=fin.entries.find(x=>x.id===id);if(r?.custodyKind)return window.crOpenCustodyEntry?.('',id);if(r)entryModal(r.type,r)},finSaveEntry:saveEntry,finDeleteEntry:deleteEntry,finCalcLive:calcLive,finSaveCalculatorDefaults:saveCalcDefaults,finSaveSettings:saveSettings,finRefresh:refresh,finSettingsCard:settings,finCalculatorCard:calculator,finEnsureLoaded:()=>finLoaded?Promise.resolve(fin):load(),finLoadInfo:()=>({loaded:finLoaded,error:loadError}),getFinanceState:()=>fin});if((location.pathname.split('/').pop()||'').toLowerCase()==='finance.html')load()}
